package ledger

import (
	"encoding/hex"
	"fmt"
	"testing"
)

// Cross-implementation compatibility: these vectors were generated by
// the Rust reference implementation (enclave-os-mini
// crates/enclave-os-merkle) running the identical scenario. A Go store
// sharing the commitment key must reproduce every root byte for byte,
// and Rust-generated proofs must verify here.
//
// Generator: a #[test] against MerkleStore<MemBackend> with
// ck[i] = i, sk[i] = 0xA0 + i, printing (version, root) after each
// batch and the encoded proofs at the final root.

const (
	goldenRoot1 = "b8720446c3642c5bd577aa53037aca191f56c501b970a27615883e6d3cf6d293"
	goldenRoot2 = "8a46f27b42fa87ea9d775ebbff9baa7cf2ee8a45b33b2c99793c3a53b91e8296"
	goldenRoot3 = "4548a48a342960e9a51d46f46c756911b4816ac3a4bf5aa442f339f6ce7696f0"
	goldenRoot4 = "3fa0445343dbe12a68aa2552902ec55063e6b923ee219bcdefb61cc4aae82b86"
	goldenRoot5 = "0eae295f13c47f2efeb41cef9006d5ee1a6610d2087faaff7d061ac7c3b83a96"

	goldenProofAlice  = ""
	goldenProofAbsent = ""
)

func goldenKeys() ([KeySize]byte, [KeySize]byte) {
	var ck, sk [KeySize]byte
	for i := 0; i < KeySize; i++ {
		ck[i] = byte(i)
		sk[i] = byte(0xA0 + i)
	}
	return ck, sk
}

func mustHexRoot(t *testing.T, s string) Hash {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil || len(b) != HashSize {
		t.Fatalf("bad golden root %q", s)
	}
	var h Hash
	copy(h[:], b)
	return h
}

func TestRustCompatibilityRoots(t *testing.T) {
	ck, sk := goldenKeys()
	s, err := Create(NewMemBackend(), ck, sk)
	if err != nil {
		t.Fatal(err)
	}

	check := func(step string, want string, root Hash, version, wantVersion uint64) {
		t.Helper()
		if version != wantVersion {
			t.Fatalf("%s: version %d, want %d", step, version, wantVersion)
		}
		if root != mustHexRoot(t, want) {
			t.Fatalf("%s: root %x, want %s", step, root, want)
		}
	}

	r, v, err := s.PutBatch([]Op{
		Put([]byte("alice"), []byte("1000")),
		Put([]byte("bob"), []byte("250")),
	})
	if err != nil {
		t.Fatal(err)
	}
	check("step1", goldenRoot1, r, v, 1)

	r, v, err = s.PutBatch([]Op{
		Put([]byte("carol"), []byte("7")),
		Put([]byte("dave"), []byte{}),
		Put([]byte("alice"), []byte("1001")),
	})
	if err != nil {
		t.Fatal(err)
	}
	check("step2", goldenRoot2, r, v, 2)

	r, v, err = s.PutBatch([]Op{
		Del([]byte("bob")),
		Put([]byte("eve"), []byte("zzz")),
	})
	if err != nil {
		t.Fatal(err)
	}
	check("step3", goldenRoot3, r, v, 3)

	var ops []Op
	for i := 0; i < 100; i++ {
		ops = append(ops, Put(
			[]byte(fmt.Sprintf("key-%03d", i)),
			[]byte(fmt.Sprintf("value-%03d", i))))
	}
	r, v, err = s.PutBatch(ops)
	if err != nil {
		t.Fatal(err)
	}
	check("step4", goldenRoot4, r, v, 4)

	var dels []Op
	for i := 0; i < 100; i += 2 {
		dels = append(dels, Del([]byte(fmt.Sprintf("key-%03d", i))))
	}
	r, v, err = s.PutBatch(dels)
	if err != nil {
		t.Fatal(err)
	}
	check("step5", goldenRoot5, r, v, 5)

	// A Go-generated proof for the same state matches the Rust encoding
	// byte for byte (the descent is deterministic).
	proofAlice, err := s.Prove([]byte("alice"))
	if err != nil {
		t.Fatal(err)
	}
	if hex.EncodeToString(proofAlice.Encode()) != goldenProofAlice {
		t.Fatal("alice proof encoding differs from the Rust reference")
	}
}

func TestRustCompatibilityProofs(t *testing.T) {
	// Rust-generated proofs verify against the Rust-generated root,
	// through the Go verifier, including the value commitment check.
	ck, sk := goldenKeys()
	s, err := Create(NewMemBackend(), ck, sk)
	if err != nil {
		t.Fatal(err)
	}
	root := mustHexRoot(t, goldenRoot5)

	rawInc, err := hex.DecodeString(goldenProofAlice)
	if err != nil {
		t.Fatal(err)
	}
	inc, err := DecodeProof(rawInc)
	if err != nil {
		t.Fatalf("decode rust inclusion proof: %v", err)
	}
	ok, err := s.VerifyValue(&root, []byte("alice"), []byte("1001"), inc)
	if err != nil || !ok {
		t.Fatalf("rust inclusion proof failed in go: %v", err)
	}
	if ok, _ := s.VerifyValue(&root, []byte("alice"), []byte("forged"), inc); ok {
		t.Fatal("rust proof verified a forged value")
	}

	rawAbs, err := hex.DecodeString(goldenProofAbsent)
	if err != nil {
		t.Fatal(err)
	}
	abs, err := DecodeProof(rawAbs)
	if err != nil {
		t.Fatalf("decode rust absence proof: %v", err)
	}
	ok, err = s.VerifyAbsent(&root, []byte("absent-key"), abs)
	if err != nil || !ok {
		t.Fatalf("rust absence proof failed in go: %v", err)
	}
}
